package org.fruittwingpt.config;
import org.fruittwingpt.domain.AppUser; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.oauth2.jose.jws.MacAlgorithm; import org.springframework.security.oauth2.jwt.*; import org.springframework.stereotype.Service; import java.time.*;
@Service public class TokenService { private final JwtEncoder encoder; private final long expiry; public TokenService(JwtEncoder encoder,@Value("${app.jwt.expiry-minutes}") long expiry){this.encoder=encoder;this.expiry=expiry;} public String create(AppUser user){ var now=Instant.now(); var claims=JwtClaimsSet.builder().subject(user.email).issuedAt(now).expiresAt(now.plus(Duration.ofMinutes(expiry))).claim("role",user.role).build(); var header=JwsHeader.with(MacAlgorithm.HS256).type("JWT").build(); return encoder.encode(JwtEncoderParameters.from(header,claims)).getTokenValue(); } }
